#!/bin/bash
set -eo pipefail
umask 027
export PYTHONNOUSERSITE=1 PYTHONDONTWRITEBYTECODE=1
/data1/home/sunyiq/miniconda3/envs/knet_clean/bin/python -B - <<'PY'
import base64, hashlib, io, json, os, pwd, stat, zipfile
from pathlib import Path
phase=Path('/data1/home/sunyiq/kalmannet_tukf09_four_failed_basins_20261003_attempt1')
raw=base64.b64decode('',validate=True)
if hashlib.sha256(raw).hexdigest()!='e8fd8432106756d907e20cd1819c7e94a1637b5551c6f45ebd98da0dea9608d9' or pwd.getpwuid(os.getuid()).pw_name!='sunyiq':
    raise SystemExit('deployment payload or account changed')
if phase.exists() or phase.is_symlink() or not phase.parent.is_dir() or phase.parent.resolve()!=phase.parent:
    raise SystemExit('exclusive destination occupied or parent linked')
with zipfile.ZipFile(io.BytesIO(raw)) as archive:
    names=archive.namelist()
    if len(names)!=len(set(names)) or any('/' in n or ':' in n for n in names):
        raise SystemExit('unsafe deployment archive')
    members={n:archive.read(n) for n in names}
manifest_raw=members['payload_manifest.json']
if hashlib.sha256(manifest_raw).hexdigest()!='590981edde63612507d2d18468baf1585fd0bafc825b44a7030778391c9e8b37':
    raise SystemExit('manifest fingerprint changed')
manifest=json.loads(manifest_raw)
if manifest['remote_phase']!=phase.as_posix() or set(members)!=set(manifest['files'])|{'payload_manifest.json'}:
    raise SystemExit('manifest identity or members changed')
for name,expected in manifest['files'].items():
    value=members[name]
    if expected!={'sha256':hashlib.sha256(value).hexdigest(),'size_bytes':len(value)}:
        raise SystemExit('member fingerprint changed: '+name)
phase.mkdir(mode=0o750,exist_ok=False)
for directory in ('control','exports',*(f'basin_{row["basin_id"]}' for row in manifest['authorized'])):
    (phase/directory).mkdir(mode=0o750,exist_ok=False)
for row in manifest['authorized']:
    root=phase/f'basin_{row["basin_id"]}'
    for directory in ('control','logs','tmp','cache'):
        (root/directory).mkdir(mode=0o750,exist_ok=False)
for name,value in members.items():
    with (phase/name).open('xb') as stream:
        stream.write(value); stream.flush(); os.fsync(stream.fileno())
for row in manifest['authorized']:
    value={'status':'FOUR_FAILED_BASIN_STAGED_NOT_SUBMITTED',**row,'manifest_sha256':'590981edde63612507d2d18468baf1585fd0bafc825b44a7030778391c9e8b37','archive_sha256':'e8fd8432106756d907e20cd1819c7e94a1637b5551c6f45ebd98da0dea9608d9','scheduler_submission_performed':False}
    with (phase/f'basin_{row["basin_id"]}/control/deployment.json').open('x',encoding='utf-8') as stream:
        json.dump(value,stream,sort_keys=True,separators=(',',':')); stream.write(chr(10)); stream.flush(); os.fsync(stream.fileno())
print('FOUR_FAILED_DEPLOYED_NOT_SUBMITTED '+json.dumps({'archive_sha256':'e8fd8432106756d907e20cd1819c7e94a1637b5551c6f45ebd98da0dea9608d9','manifest_sha256':'590981edde63612507d2d18468baf1585fd0bafc825b44a7030778391c9e8b37','basin_count':4,'scheduler_submissions':0,'evaluation_array_reads':0},sort_keys=True))
PY
